{
  "name": "微孔板揭膜机",
  "name_en": "Microplate Peeler",
  "manufacturer": "",
  "description": "用于自动剥离微孔板顶部封膜或粘性封板膜的实验室设备，常用于样品处理和自动化工作流中，在后续移液、读板或分析前打开微孔板。",
  "description_en": "A laboratory device used to automatically remove sealing films or adhesive seals from microplates. It is commonly used in sample-processing and automated workflows to open plates before pipetting, plate reading, or analysis.",
  "actions": [
    {
      "action_name": "auto-peel",
      "description": "自动剥离微孔板封膜。",
      "description_en": "Automatically peel the seal or film from a microplate."
    },
    {
      "action_name": "auto-restart",
      "description": "重启揭膜机。",
      "description_en": "Restart the microplate peeler."
    }
  ],
  "tag_hints": [
    "microplate peeler",
    "plate de-sealing",
    "seal removal",
    "lab automation",
    "sample preparation"
  ]
}

